<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence;
use App\Application\Repositories\TransferRepository;
use App\Application\Read\Page;
use App\Application\Exceptions\OperationConflict;
use PDO;
final class PdoTransferRepository extends PdoRepository implements TransferRepository {
 public function installed():bool {return (bool)$this->rows("SELECT id FROM schema_migrations WHERE id='20261103090300_register_transfer_permissions'");}
 public function coverageInstalled():bool {return (bool)$this->rows("SELECT id FROM schema_migrations WHERE id='20261113090000_add_quote_transfer_coverage'");}
 private function rows(string $sql,array $args=[]):array {$s=$this->pdo()->prepare($sql);$s->execute($args);return $s->fetchAll();}
 private function execute(string $sql,array $args):void {$s=$this->pdo()->prepare($sql);$s->execute($args);}
 private function scope(?array $allowed,array &$args):string {if($allowed===null)return '';if(!$allowed)return ' AND 1=0';$ids=array_map(fn($v)=>self::id((int)$v),$allowed);$list=implode(',',$ids);return " AND (t.source_branch_id IN ($list) OR t.destination_branch_id IN ($list))";}
 public function listing(string $search,string $status,?int $branch,?array $allowed,int $offset):Page {
  if(strlen($search)>120||$offset<0||($status!==''&&!isset(\App\Domain\Transfers\TransferRules::LABELS[$status])))throw new \InvalidArgumentException('Revisa los filtros.');
  $args=[];$where=$this->scope($allowed,$args);if($search!==''){$where.=' AND (t.folio LIKE ? OR s.name LIKE ? OR d.name LIKE ?)';$term='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$search).'%';$args=[$term,$term,$term];}if($status!==''){$where.=' AND t.status=?';$args[]=$status;}if($branch){$where.=' AND (t.source_branch_id=? OR t.destination_branch_id=?)';$args[]=$branch;$args[]=$branch;}
  $rows=$this->rows('SELECT t.*,s.name source_name,d.name destination_name,u.display_name actor_name,(SELECT COUNT(*) FROM transfer_items WHERE transfer_id=t.id) item_count FROM transfers t JOIN branches s ON s.id=t.source_branch_id JOIN branches d ON d.id=t.destination_branch_id JOIN users u ON u.id=t.created_by WHERE 1=1'.$where.' ORDER BY t.id DESC LIMIT 26 OFFSET '.(int)$offset,$args);$more=count($rows)>25;if($more)array_pop($rows);return new Page($rows,25,$offset,$more);
 }
 public function find(int $id,?array $allowed=null,bool $lock=false):?array {$args=[$id];$scope=$this->scope($allowed,$args);if($lock)return $this->rows('SELECT t.* FROM transfers t WHERE t.id=?'.$scope.' FOR UPDATE',$args)[0]??null;return $this->rows('SELECT t.*,s.name source_name,d.name destination_name,v.quote_id linked_quote_id FROM transfers t JOIN branches s ON s.id=t.source_branch_id JOIN branches d ON d.id=t.destination_branch_id LEFT JOIN quote_versions v ON v.id=t.quote_version_id WHERE t.id=?'.$scope.($lock?' FOR UPDATE':''),$args)[0]??null;}
 public function items(int $id,bool $lock=false):array {$released=$this->coverageInstalled()?'ti.source_released_quantity':'0 source_released_quantity';return $this->rows('SELECT ti.*,'.$released.',pv.sku,pv.name variant_name,p.name product_name,u.symbol,u.decimal_places,ti.approved_quantity-ti.dispatched_quantity-'.($this->coverageInstalled()?'ti.source_released_quantity':'0').' pending_dispatch,ti.dispatched_quantity-ti.received_quantity in_transit FROM transfer_items ti JOIN product_variants pv ON pv.id=ti.variant_id JOIN products p ON p.id=pv.product_id JOIN units u ON u.id=ti.unit_id WHERE transfer_id=? ORDER BY ti.variant_id,ti.id'.($lock?' FOR UPDATE':''),[$id]);}
 public function operation(string $key):?array {return $this->rows('SELECT * FROM transfer_events WHERE operation_key=?',[$key])[0]??null;}
 public function create(array $d):int {$this->execute('INSERT INTO transfers(folio,source_branch_id,destination_branch_id,quote_version_id,reason,created_by) VALUES(?,?,?,?,?,?)',array_values($d));return $this->insertedId();}
 public function addItem(array $d):int {$this->execute('INSERT INTO transfer_items(transfer_id,variant_id,unit_id,requested_quantity) VALUES(?,?,?,?)',array_values($d));return $this->insertedId();}
 public function update(int $id,string $status,?int $approver=null):void {$this->execute('UPDATE transfers SET status=?,lock_version=lock_version+1,approved_by=COALESCE(?,approved_by),approved_at=CASE WHEN ? IS NOT NULL THEN UTC_TIMESTAMP(6) ELSE approved_at END WHERE id=?',[$status,$approver,$approver,$id]);}
 public function quantities(int $id,array $data):void {$fields=['requested_quantity','approved_quantity','source_released_quantity','dispatched_quantity','received_quantity','destination_reserved'];$sets=[];$args=[];foreach($data as $k=>$v){if(!in_array($k,$fields,true))throw new \LogicException('Invalid transfer field');$sets[]=$k.'=?';$args[]=$v;}$args[]=$id;$this->execute('UPDATE transfer_items SET '.implode(',',$sets).' WHERE id=?',$args);}
 public function event(array $d):int {$this->execute('INSERT INTO transfer_events(transfer_id,action,from_status,to_status,operation_key,request_hash,actor_user_id,branch_id,notes) VALUES(?,?,?,?,?,?,?,?,?)',array_values($d));return $this->insertedId();}
 public function finishEvent(int $id,string $status):void {$this->execute('UPDATE transfer_events SET to_status=? WHERE id=?',[$status,$id]);}
 public function eventItem(int $event,int $item,string $quantity,?int $movement):void {$this->execute('INSERT INTO transfer_event_items(event_id,transfer_item_id,quantity,inventory_movement_id) VALUES(?,?,?,?)',[$event,$item,$quantity,$movement]);}
 public function history(int $id):array {return $this->rows('SELECT e.*,u.display_name actor_name,ei.transfer_item_id,ei.quantity,ei.inventory_movement_id FROM transfer_events e JOIN users u ON u.id=e.actor_user_id LEFT JOIN transfer_event_items ei ON ei.event_id=e.id WHERE e.transfer_id=? ORDER BY e.id,ei.id',[$id]);}
 public function coverageHistory(int $id):array {if(!$this->coverageInstalled())return [];return $this->rows('SELECT e.*,u.display_name actor_name,ci.variant_id FROM transfer_coverage_events e JOIN users u ON u.id=e.actor_user_id JOIN transfer_quote_coverage_items ci ON ci.id=e.coverage_item_id WHERE e.transfer_id=? ORDER BY e.id',[$id]);}
 public function quoteOptions(?array $allowed):array {if($allowed===[])return [];$where=$allowed===null?'':' AND q.branch_id IN ('.implode(',',array_map(fn($id)=>self::id((int)$id),$allowed)).')';return $this->rows("SELECT v.id,q.folio,q.branch_id,q.status quote_status,v.status version_status,b.name branch_name FROM quotes q JOIN quote_versions v ON v.quote_id=q.id AND v.version_number=q.current_version JOIN branches b ON b.id=q.branch_id WHERE ((v.status='draft' AND q.status IN('preparing','pending_approval')) OR (v.status='issued' AND q.status IN('sent','accepted')))".$where.' ORDER BY q.id DESC LIMIT 200');}
 public function branches():array {return $this->rows('SELECT id,name,is_active FROM branches WHERE is_active=1 ORDER BY name,id LIMIT 1000');}
 public function lockBranches(array $ids,bool $allowInactive=false):void {sort($ids);foreach(array_unique($ids)as $id){$b=$this->rows('SELECT id,is_active FROM branches WHERE id=? FOR UPDATE',[$id])[0]??null;if(!$b||(!$allowInactive&&(int)$b['is_active']!==1))throw new OperationConflict('La sucursal está inactiva o no existe.');}}
 public function lockQuote(int $id):void {$this->rows('SELECT id FROM quotes WHERE id=? FOR UPDATE',[$id]);}
 public function quoteVersion(int $id,bool $lock=false):?array {return $this->rows('SELECT qv.*,q.status quote_status,q.branch_id,q.id quote_id,q.current_version FROM quote_versions qv JOIN quotes q ON q.id=qv.quote_id WHERE qv.id=?'.($lock?' FOR UPDATE':''),[$id])[0]??null;}
 public function quoteItems(int $version):array {return $this->rows('SELECT * FROM quote_items WHERE quote_version_id=? ORDER BY position,id',[$version]);}
 public function createQuoteSnapshot(int $transfer,int $version,string $hash,string $snapshot,int $actor):int {$this->execute('INSERT INTO transfer_quote_snapshots(transfer_id,quote_version_id,content_hash,snapshot_json,created_by) VALUES(?,?,?,?,?)',[$transfer,$version,$hash,$snapshot,$actor]);return $this->insertedId();}
 public function addCoverageItem(int $snapshot,int $transferItem,int $variant,int $unit,string $quotedQuantity):int {$this->execute('INSERT INTO transfer_quote_coverage_items(snapshot_id,transfer_item_id,variant_id,unit_id,quoted_quantity) VALUES(?,?,?,?,?)',[$snapshot,$transferItem,$variant,$unit,$quotedQuantity]);return $this->insertedId();}
 public function coverageEvent(int $transfer,int $coverageItem,string $action,string $quantity,int $actor,string $reason):void {$this->execute('INSERT INTO transfer_coverage_events(transfer_id,coverage_item_id,action,quantity,actor_user_id,reason) VALUES(?,?,?,?,?,?)',[$transfer,$coverageItem,$action,$quantity,$actor,$reason]);}
 public function coverageSnapshot(int $transfer,bool $lock=false):?array {return $this->rows('SELECT * FROM transfer_quote_snapshots WHERE transfer_id=?'.($lock?' FOR UPDATE':''),[$transfer])[0]??null;}
 public function coverageItemsForTransfer(int $transfer,bool $lock=false):array {if(!$this->coverageInstalled())return [];return $this->rows('SELECT ci.*,s.transfer_id,t.source_branch_id,t.destination_branch_id,t.status transfer_status,ti.requested_quantity,ti.approved_quantity,ti.source_released_quantity,ti.dispatched_quantity,ti.received_quantity FROM transfer_quote_coverage_items ci JOIN transfer_quote_snapshots s ON s.id=ci.snapshot_id JOIN transfers t ON t.id=s.transfer_id JOIN transfer_items ti ON ti.id=ci.transfer_item_id WHERE s.transfer_id=? ORDER BY ci.variant_id,ci.id'.($lock?' FOR UPDATE':''),[$transfer]);}
 public function coverageItemsForVersion(int $version,bool $lock=false):array {if(!$this->coverageInstalled())return [];return $this->rows('SELECT ci.*,s.transfer_id,t.source_branch_id,t.destination_branch_id,t.status transfer_status,ti.requested_quantity,ti.approved_quantity,ti.source_released_quantity,ti.dispatched_quantity,ti.received_quantity FROM transfer_quote_coverage_items ci JOIN transfer_quote_snapshots s ON s.id=ci.snapshot_id JOIN transfers t ON t.id=s.transfer_id JOIN transfer_items ti ON ti.id=ci.transfer_item_id WHERE s.quote_version_id=? ORDER BY t.id,ci.variant_id,ci.id'.($lock?' FOR UPDATE':''),[$version]);}
 public function invalidateCoverageItem(int $coverageItem,string $released,int $actor,string $reason):void {$this->execute("UPDATE transfer_quote_coverage_items ci JOIN transfer_items ti ON ti.id=ci.transfer_item_id SET ci.status='invalidated',ci.invalidated_at=UTC_TIMESTAMP(6),ci.invalidated_by=?,ci.invalidation_reason=?,ti.source_released_quantity=ti.source_released_quantity+? WHERE ci.id=? AND ci.status='active'",[$actor,$reason,$released,$coverageItem]);}
 public function quoteNeed(int $version,int $variant):string {
  if(!$this->coverageInstalled()){$row=$this->rows("SELECT qi.quantity-COALESCE((SELECT SUM(ri.quantity-ri.released_quantity) FROM inventory_reservation_items ri JOIN inventory_reservations r ON r.id=ri.reservation_id WHERE ri.quote_item_id=qi.id AND r.status='active'),0)-COALESCE((SELECT SUM(ti.approved_quantity) FROM transfer_items ti JOIN transfers t ON t.id=ti.transfer_id WHERE t.quote_version_id=qi.quote_version_id AND ti.variant_id=qi.variant_id AND t.status IN('approved','prepared','in_transit','received')),0) quantity FROM quote_items qi WHERE qi.quote_version_id=? AND qi.variant_id=?",[$version,$variant])[0]??null;if(!$row)throw new OperationConflict('La variante no pertenece a la cotización.');return (string)$row['quantity'];}
  $row=$this->rows("SELECT GREATEST(qi.quantity-CASE WHEN q.status='accepted' THEN COALESCE((SELECT SUM(ri.quantity-ri.released_quantity) FROM inventory_reservation_items ri JOIN inventory_reservations r ON r.id=ri.reservation_id WHERE ri.quote_item_id=qi.id AND r.status='active'),0)+COALESCE((SELECT SUM(ti.approved_quantity) FROM transfer_quote_coverage_items ci JOIN transfer_quote_snapshots s ON s.id=ci.snapshot_id JOIN transfer_items ti ON ti.id=ci.transfer_item_id JOIN transfers t ON t.id=ti.transfer_id WHERE s.quote_version_id=qi.quote_version_id AND ci.variant_id=qi.variant_id AND ci.status='active' AND t.status IN('approved','prepared','in_transit','received')),0) ELSE COALESCE((SELECT ib.available_quantity FROM inventory_balances ib WHERE ib.branch_id=q.branch_id AND ib.variant_id=qi.variant_id AND ib.initialized_at IS NOT NULL),0)+COALESCE((SELECT SUM(ti.approved_quantity-ti.received_quantity) FROM transfer_quote_coverage_items ci JOIN transfer_quote_snapshots s ON s.id=ci.snapshot_id JOIN transfer_items ti ON ti.id=ci.transfer_item_id JOIN transfers t ON t.id=ti.transfer_id WHERE s.quote_version_id=qi.quote_version_id AND ci.variant_id=qi.variant_id AND ci.status='active' AND t.status IN('approved','prepared','in_transit')),0) END,0) quantity FROM quote_items qi JOIN quote_versions qv ON qv.id=qi.quote_version_id JOIN quotes q ON q.id=qv.quote_id WHERE qi.quote_version_id=? AND qi.variant_id=?",[$version,$variant])[0]??null;
  if(!$row)throw new OperationConflict('La variante no pertenece a la cotización.');return (string)$row['quantity'];
 }
 public function coverage(int $version,int $variant):string {if(!$this->coverageInstalled())return (string)$this->rows("SELECT COALESCE(SUM(ti.approved_quantity-ti.received_quantity),0) quantity FROM transfer_items ti JOIN transfers t ON t.id=ti.transfer_id WHERE t.quote_version_id=? AND ti.variant_id=? AND t.status IN('approved','prepared','in_transit')",[$version,$variant])[0]['quantity'];return (string)$this->rows("SELECT COALESCE(SUM(ti.approved_quantity-ti.received_quantity),0) quantity FROM transfer_quote_coverage_items ci JOIN transfer_quote_snapshots s ON s.id=ci.snapshot_id JOIN transfer_items ti ON ti.id=ci.transfer_item_id JOIN transfers t ON t.id=ti.transfer_id WHERE s.quote_version_id=? AND ci.variant_id=? AND ci.status='active' AND t.status IN('approved','prepared','in_transit')",[$version,$variant])[0]['quantity'];}
 public function destinationReservations(int $version):array {if(!$this->coverageInstalled())return $this->rows('SELECT ti.* ,t.destination_branch_id branch_id FROM transfer_items ti JOIN transfers t ON t.id=ti.transfer_id WHERE t.quote_version_id=? AND ti.destination_reserved>ti.destination_released ORDER BY ti.variant_id,ti.id FOR UPDATE',[$version]);return $this->rows("SELECT ti.* ,t.destination_branch_id branch_id FROM transfer_quote_coverage_items ci JOIN transfer_quote_snapshots s ON s.id=ci.snapshot_id JOIN transfer_items ti ON ti.id=ci.transfer_item_id JOIN transfers t ON t.id=ti.transfer_id WHERE s.quote_version_id=? AND ci.status='active' AND ti.destination_reserved>ti.destination_released ORDER BY ti.variant_id,ti.id FOR UPDATE",[$version]);}
 public function releaseDestination(int $item,string $consumed='0'):void {$this->execute('UPDATE transfer_items SET destination_released=destination_reserved-? WHERE id=?',[$consumed,$item]);}
 public function assertUntracked(int $variant):void {foreach(['inventory_lots','inventory_serials']as $table)if($this->rows('SELECT id FROM '.$table.' WHERE variant_id=? LIMIT 1 FOR UPDATE',[$variant]))throw new OperationConflict('Esta variante tiene lotes o series. M05 aún no ofrece un traslado trazable de esas identificaciones; no se permite perderlas.');}
}
